// ─── CONSTANTS ───────────────────────────────────────────────────────────────
const COURTS = ["Court 1", "Court 2", "Court 3"];
const HOURS = Array.from({ length: 19 }, (_, i) => i + 6);
const fmt = (h) => (h < 12 ? `${h}:00 AM` : h === 12 ? `12:00 PM` : `${h - 12}:00 PM`);
const TODAY = new Date().toISOString().split("T")[0];

function getSlotStatus(bookings, date, court, hour) {
  const b = bookings.find(
    (b) => b.date === date && b.court === court && hour >= b.startHour && hour < b.endHour
      && b.status !== "cancelled"
  );
  return b ? b.status : "available";
}

function hasConflict(bookings, date, court, startHour, endHour, excludeId) {
  return bookings.some(
    (b) =>
      b.id !== excludeId &&
      b.date === date &&
      b.court === court &&
      b.status !== "cancelled" &&
      startHour < b.endHour &&
      endHour > b.startHour
  );
}

function formatDate(dateStr) {
  const d = new Date(dateStr + "T00:00:00");
  return d.toLocaleDateString("en-PH", { weekday: "long", year: "numeric", month: "long", day: "numeric" });
}

function calcHours(start, end) { return end - start; }

