// ─── AVAILABILITY PAGE ────────────────────────────────────────────────────────

function AvailabilityPage({ bookings, loading, openBooking }) {
  const [selDate, setSelDate] = useState(TODAY);

  function changeDate(delta) {
    const d = new Date(selDate + "T00:00:00");
    d.setDate(d.getDate() + delta);
    setSelDate(d.toISOString().split("T")[0]);
  }

  return (
    <div className="page">
      <div className="page-inner">
        <div className="page-header" style={{display:"flex",justifyContent:"space-between",alignItems:"flex-start",flexWrap:"wrap",gap:"1rem"}}>
          <div>
            <h2 className="page-title">Court Availability</h2>
            <p className="page-sub">Green = Available (tap to book). Red = Reserved. Yellow = Ongoing.</p>
          </div>
          <div className="live-badge"><span className="live-dot"/>Live Updates</div>
        </div>
        <div className="date-row">
          <div style={{display:"flex",gap:".5rem"}}>
            <button className="date-nav-btn" onClick={() => changeDate(-1)}>←</button>
            <button className="date-nav-btn" onClick={() => changeDate(1)}>→</button>
          </div>
          <input type="date" className="date-input" value={selDate} min={TODAY}
            onChange={(e) => setSelDate(e.target.value)} />
          <span className="date-label">{formatDate(selDate)}</span>
        </div>
        <div className="legend">
          {[["var(--green)","Available"],["var(--red)","Reserved"],["var(--yellow)","Ongoing"]].map(([c,l]) => (
            <div className="legend-item" key={l}><div className="legend-dot" style={{background:c}}/>{l}</div>
          ))}
        </div>
        <div className="avail-table-wrap">
          {loading ? <Spinner text="Loading schedule..." /> : (
            <table className="avail-table">
              <thead>
                <tr>
                  <th>Time</th>
                  {COURTS.map((c) => <th key={c}>{c}</th>)}
                </tr>
              </thead>
              <tbody>
                {HOURS.map((h) => (
                  <tr key={h}>
                    <td className="time-cell">{fmt(h)}</td>
                    {COURTS.map((court) => {
                      const status = getSlotStatus(bookings, selDate, court, h);
                      return (
                        <td key={court}>
                          <button
                            className={`slot slot-${status}`}
                            disabled={status !== "available"}
                            onClick={() => openBooking(court, selDate, h)}>
                            <span className="slot-dot"/>
                            {status === "available" ? "Available" : status === "reserved" ? "Reserved" : "Ongoing"}
                          </button>
                        </td>
                      );
                    })}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  );
}

// ─── BOOKING TABLE ────────────────────────────────────────────────────────────

function BookingTable({ bookings, loading, onCancel, onOngoing, onReserved, showDate }) {
  if (loading) return <Spinner text="Loading bookings..." />;
  if (!bookings.length) {
    return (
      <div style={{padding:"3rem",textAlign:"center",color:"var(--gray-400)"}}>
        <div style={{fontSize:"2.5rem",marginBottom:".75rem"}}>📭</div>
        <div style={{fontWeight:600}}>No bookings found</div>
      </div>
    );
  }
  return (
    <div style={{overflowX:"auto"}}>
      <table className="bt">
        <thead>
          <tr>
            {showDate && <th>Date</th>}
            <th>Court</th><th>Start</th><th>End</th><th>Hrs</th>
            <th>Name</th><th>Contact</th><th>Status</th><th>Actions</th>
          </tr>
        </thead>
        <tbody>
          {[...bookings].sort((a,b) => a.startHour - b.startHour).map((b) => (
            <tr key={b.id}>
              {showDate && <td>{b.date}</td>}
              <td><strong>{b.court}</strong></td>
              <td style={{whiteSpace:"nowrap"}}>{fmt(b.startHour)}</td>
              <td style={{whiteSpace:"nowrap"}}>{fmt(b.endHour)}</td>
              <td><span className="badge badge-gray">{calcHours(b.startHour,b.endHour)}h</span></td>
              <td>{b.name}</td>
              <td>{b.phone}</td>
              <td>
                <span className={`badge badge-${b.status==="reserved"?"red":b.status==="ongoing"?"yellow":"gray"}`}>
                  {b.status}
                </span>
              </td>
              <td>
                <div className="table-actions">
                  {b.status === "reserved" && (
                    <button className="btn-warning" onClick={() => onOngoing(b.id)}>▶ Start</button>
                  )}
                  {b.status === "ongoing" && (
                    <button className="btn-gray" style={{fontSize:".8rem",padding:".4rem .8rem"}} onClick={() => onReserved(b.id)}>↩ Reset</button>
                  )}
                  <button className="btn-danger" onClick={() => onCancel(b.id)}>✕ Cancel</button>
                </div>
              </td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

// ─── ADMIN PAGE ───────────────────────────────────────────────────────────────

function AdminPage({ bookings, loading, setBookings, addToast }) {
  const [tab, setTab] = useState("dashboard");
  const [filterDate, setFilterDate] = useState(TODAY);

  const todayBookings = bookings.filter((b) => b.date === TODAY);
  const weekBookings = bookings.filter((b) => {
    const diff = (new Date(b.date + "T00:00:00") - new Date()) / 86400000;
    return diff >= -1 && diff <= 6;
  });
  const totalHours = bookings.reduce((acc,b) => acc + calcHours(b.startHour,b.endHour), 0);

  async function cancelBooking(id) {
    if (!confirm("Cancel this booking?")) return;
    try {
      await deleteBooking(id);
      setBookings((prev) => prev.filter((b) => b.id !== id));
      addToast("Booking cancelled", "success");
    } catch {
      addToast("Failed to cancel booking", "error");
    }
  }

  async function markOngoing(id) {
    try {
      const updated = await updateBookingStatus(id, "ongoing");
      setBookings((prev) => prev.map((b) => b.id === id ? updated : b));
      addToast("Marked as ongoing", "success");
    } catch {
      addToast("Failed to update status", "error");
    }
  }

  async function markReserved(id) {
    try {
      const updated = await updateBookingStatus(id, "reserved");
      setBookings((prev) => prev.map((b) => b.id === id ? updated : b));
      addToast("Status reset", "success");
    } catch {
      addToast("Failed to update status", "error");
    }
  }

  const filteredBookings = tab === "daily" ? bookings.filter((b) => b.date === filterDate)
    : tab === "weekly" ? weekBookings : bookings;

  const TABS = [
    {id:"dashboard",label:"Dashboard",icon:"📊"},
    {id:"daily",label:"Daily View",icon:"📅"},
    {id:"weekly",label:"Weekly",icon:"📆"},
    {id:"all",label:"All Bookings",icon:"📋"},
  ];

  return (
    <div className="admin-layout">
      <div className="admin-sidebar">
        <img src={LOGO_URI} alt="BNJ Pickle Yard" className="admin-sidebar-logo"/>
        <div style={{fontFamily:"'Syne',sans-serif",fontWeight:700,fontSize:".85rem",color:"rgba(255,255,255,.4)",padding:"0 .75rem",marginBottom:"1rem"}}>
          Admin Panel
        </div>
        <div className="admin-sidebar-title">Navigation</div>
        {TABS.map((t) => (
          <button key={t.id} className={`admin-sidebar-btn ${tab===t.id?"active":""}`} onClick={() => setTab(t.id)}>
            <span>{t.icon}</span>{t.label}
          </button>
        ))}
      </div>

      <div className="admin-main">
        {tab === "dashboard" && (
          <>
            <div style={{marginBottom:"1.5rem",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:"1rem"}}>
              <div>
                <h2 className="page-title">Dashboard</h2>
                <p className="page-sub">Today: {formatDate(TODAY)}</p>
              </div>
              <div className="live-badge"><span className="live-dot"/>Live Data</div>
            </div>
            <div className="admin-stats-grid">
              {[
                {label:"Total Bookings",val:bookings.length,sub:"All time"},
                {label:"Today",val:todayBookings.length,sub:"Scheduled today"},
                {label:"Ongoing",val:bookings.filter(b=>b.status==="ongoing").length,sub:"Currently playing"},
                {label:"Total Hours",val:totalHours,sub:"Court-hours booked"},
              ].map((s) => (
                <div className="stat-card" key={s.label}>
                  <div className="stat-card-label">{s.label}</div>
                  <div className="stat-card-val">{loading?"…":s.val}</div>
                  <div className="stat-card-sub">{s.sub}</div>
                </div>
              ))}
            </div>
            <div className="table-wrap">
              <div className="table-header">
                <div className="table-title">Today's Bookings</div>
                <span className="badge badge-green">{todayBookings.length} bookings</span>
              </div>
              <BookingTable bookings={todayBookings} loading={loading} onCancel={cancelBooking} onOngoing={markOngoing} onReserved={markReserved}/>
            </div>
          </>
        )}
        {(tab==="daily"||tab==="weekly"||tab==="all") && (
          <>
            <div style={{marginBottom:"1.5rem",display:"flex",justifyContent:"space-between",alignItems:"center",flexWrap:"wrap",gap:".75rem"}}>
              <div>
                <h2 className="page-title">
                  {tab==="daily"?"Daily View":tab==="weekly"?"Weekly Schedule":"All Bookings"}
                </h2>
                <p className="page-sub">{filteredBookings.length} booking{filteredBookings.length!==1?"s":""}</p>
              </div>
              {tab==="daily" && (
                <input type="date" className="date-input" value={filterDate}
                  onChange={(e) => setFilterDate(e.target.value)}/>
              )}
            </div>
            <div className="table-wrap">
              <BookingTable bookings={filteredBookings} loading={loading} onCancel={cancelBooking} onOngoing={markOngoing} onReserved={markReserved} showDate/>
            </div>
          </>
        )}
      </div>
    </div>
  );
}

// ─── ROOT APP ─────────────────────────────────────────────────────────────────

export default function App() {
  const [page, setPage] = useState("home");
  const [bookings, setBookings] = useState([]);
  const [loading, setLoading] = useState(true);
  const [dbError, setDbError] = useState("");
  const [bookingModal, setBookingModal] = useState(null);
  const [darkMode, setDarkMode] = useState(false);
  const [toasts, setToasts] = useState([]);
  const [mobileNav, setMobileNav] = useState(false);

  // Load bookings on mount
  useEffect(() => {
    loadBookings();
  }, []);

  // Subscribe to real-time changes
  useEffect(() => {
    const channel = subscribeToBookings((payload) => {
      if (payload.eventType === "INSERT") {
        const newB = {
          id: payload.new.id,
          court: payload.new.court,
          date: payload.new.date,
          startHour: payload.new.start_hour,
          endHour: payload.new.end_hour,
          name: payload.new.name,
          phone: payload.new.phone,
          status: payload.new.status,
          createdAt: payload.new.created_at,
        };
        setBookings((prev) => [...prev.filter(b => b.id !== newB.id), newB]);
      } else if (payload.eventType === "UPDATE") {
        setBookings((prev) => prev.map((b) =>
          b.id === payload.new.id
            ? { ...b, status: payload.new.status }
            : b
        ));
      } else if (payload.eventType === "DELETE") {
        setBookings((prev) => prev.filter((b) => b.id !== payload.old.id));
      }
    });
    return () => { channel.unsubscribe(); };
  }, []);

  useEffect(() => {
    document.body.className = darkMode ? "dark" : "";
  }, [darkMode]);

  async function loadBookings() {
    setLoading(true);
    setDbError("");
    try {
      const data = await fetchBookings();
      setBookings(data);
    } catch (err) {
      setDbError("Could not connect to database. Check your Supabase credentials in supabase.js");
      console.error(err);
    } finally {
      setLoading(false);
    }
  }

  function addToast(message, type = "success") {
    const id = Date.now();
    setToasts((prev) => [...prev, { id, message, type }]);
    setTimeout(() => setToasts((prev) => prev.filter((t) => t.id !== id)), 3500);
  }

  function openBooking(court, date, hour) {
    setBookingModal({
      court: typeof court === "string" ? court : COURTS[0],
      date: date || TODAY,
      hour: hour ?? 9,
    });
  }

  async function handleConfirm(data) {
    const saved = await createBooking(data);
    setBookings((prev) => [...prev, saved]);
    addToast(`${data.court} booked: ${fmt(data.startHour)} – ${fmt(data.endHour)}`, "success");
    // Send email + SMS notifications (non-blocking)
    sendNotifications({ ...data, id: saved.id });
  }

  const NAV_ITEMS = [
    {id:"home",label:"Home"},
    {id:"availability",label:"Availability"},
    {id:"admin",label:"Admin"},
  ];

  return (
    <>
      <style>{css}</style>
      <nav className={`nav ${mobileNav?"mobile-nav-open":""}`}>
        <div className="nav-logo">
          <img src={LOGO_URI} alt="BNJ Pickle Yard"/>
        </div>
        <div className="nav-links">
          {NAV_ITEMS.map((n) => (
            <button key={n.id} className={`nav-btn ${page===n.id?"active":""}`}
              onClick={() => { setPage(n.id); setMobileNav(false); }}>
              {n.label}
            </button>
          ))}
          <button className="nav-btn nav-book" onClick={() => { openBooking(); setMobileNav(false); }}>Book Now</button>
          <button className="nav-btn" onClick={() => setDarkMode((d) => !d)}>{darkMode?"☀️":"🌙"}</button>
        </div>
        <div style={{display:"flex",alignItems:"center",gap:".5rem"}}>
          <button className="nav-btn" onClick={() => setDarkMode((d) => !d)}>{darkMode?"☀️":"🌙"}</button>
          <div className="nav-mobile-menu" onClick={() => setMobileNav((m) => !m)}>
            <span/><span/><span/>
          </div>
        </div>
      </nav>

      {dbError && (
        <div className="error-banner" style={{margin:"1rem 1.5rem",borderRadius:"var(--radius)"}}>
          ⚠ {dbError}
          <button className="btn-gray" style={{marginLeft:"auto",fontSize:".8rem",padding:".4rem .8rem"}}
            onClick={loadBookings}>Retry</button>
        </div>
      )}

      {page==="home" && <HomePage setPage={setPage} openBooking={openBooking}/>}
      {page==="availability" && <AvailabilityPage bookings={bookings} loading={loading} openBooking={openBooking}/>}
      {page==="admin" && <AdminPage bookings={bookings} loading={loading} setBookings={setBookings} addToast={addToast}/>}

      {bookingModal && (
        <BookingModal
          slot={bookingModal}
          bookings={bookings}
          onClose={() => setBookingModal(null)}
          onConfirm={handleConfirm}
        />
      )}

      <Toast toasts={toasts}/>

      <footer style={{background:"var(--gray-900)",color:"var(--gray-400)",padding:"2.5rem 2rem",textAlign:"center",fontSize:".85rem"}}>
        <img src={LOGO_URI} alt="BNJ Pickle Yard" style={{height:64,marginBottom:"1rem",opacity:.85}}/>
        <div>Zamboanga City · Open 6AM–9PM Daily</div>
        <div style={{marginTop:".5rem",color:"var(--gray-600)",fontSize:".78rem"}}>
          © 2025 BNJ Pickle Yard. All rights reserved. · Est. 2025
        </div>
      </footer>
    </>
  );
}
